32: <script>
33: (()=>{
34: const W=5,H=6, SAVE='steel-and-runes-save-v1';
35: const heroesSeed=[{id:'bryn',name:'Брин',role:'Страж',icon:'🛡️',hp:30,max:30,atk:7,range:1,x:1,y:5,skill:'Щитовой натиск'},{id:'lyra',name:'Лира',role:'Следопыт',icon:'🏹',hp:24,max:24,atk:6,range:3,x:2,y:5,skill:'Меткий выстрел'},{id:'oren',name:'Орен',role:'Рунник',icon:'🔮',hp:21,max:21,atk:5,range:3,x:3,y:5,skill:'Искра руны'}];
36: let state, action='attack', selected='bryn', log=[], sound=true, busy=false;
37: const terrain=['floor','moss','floor','rough','floor','floor','rough','floor','moss','floor','moss','floor','obstacle','floor','rough','floor','water','floor','moss','floor','floor','floor','rough','floor','floor','moss','floor','floor','rough','moss'];
38: const $=s=>document.querySelector(s), board=$('#board');
39: function enemiesFor(stage){let base=[{id:'raider',name:'Налётчик',icon:'👺',hp:16,max:16,atk:4,range:1,x:1,y:0},{id:'wolf',name:'Сумрачный волк',icon:'🐺',hp:13,max:13,atk:4,range:1,x:3,y:1},{id:'archer',name:'Разбойник',icon:'🏹',hp:12,max:12,atk:4,range:3,x:4,y:0}];if(stage%3===0)base.push({id:'ogre',name:'Болотный громила',icon:'👹',hp:23,max:23,atk:6,range:1,x:2,y:1});return base.map((e,i)=>({...e,id:e.id+i,hp:e.hp+Math.floor((stage-1)/2)*2,max:e.max+Math.floor((stage-1)/2)*2,atk:e.atk+Math.floor((stage-1)/3)}))}
40: function fresh(stage=1,gold=24,carry){return {stage,gold,turn:1,phase:'hero',heroes:carry||heroesSeed.map(h=>({...h})),enemies:enemiesFor(stage),used:{},defending:{},terrain:[...terrain]}}
41: function load(){try{let x=JSON.parse(localStorage.getItem(SAVE));if(x&&x.heroes&&x.enemies)return x}catch(e){}return fresh()}
42: state=load(); selected=state.heroes.find(h=>h.hp>0)?.id||null;
43: function save(){try{localStorage.setItem(SAVE,JSON.stringify(state))}catch(e){}}
44: function note(msg){let n=$('#boardNote');n.textContent=msg;n.classList.add('show');clearTimeout(note.t);note.t=setTimeout(()=>n.classList.remove('show'),2100)}
45: function toast(msg){let t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),1700)}
46: function tone(freq=360){if(!sound)return;try{let C=window.AudioContext||window.webkitAudioContext;if(!C)return;let ctx=tone.ctx||(tone.ctx=new C()),osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=freq;gain.gain.setValueAtTime(.035,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.12);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.13)}catch(e){}}
47: function addLog(text){log.unshift(text);log=log.slice(0,20);$('#logList').innerHTML=log.map(x=>`<li>${x}</li>`).join('')}
48: function units(){return [...state.heroes,...state.enemies].filter(u=>u.hp>0)}
49: function at(x,y){return units().find(u=>u.x===x&&u.y===y)}
50: function selectedUnit(){return state.heroes.find(h=>h.id===selected&&h.hp>0)}
51: function aliveEnemies(){return state.enemies.filter(e=>e.hp>0)}
52: function distance(a,b){return Math.abs(a.x-b.x)+Math.abs(a.y-b.y)}
53: function canMove(x,y,u){return x>=0&&x<W&&y>=0&&y<H&&!at(x,y)&&state.terrain[y*W+x]!=='obstacle'&&state.terrain[y*W+x]!=='water'&&Math.abs(u.x-x)+Math.abs(u.y-y)<=2}
54: function render(){
55:  $('#battleNum').textContent=String(state.stage).padStart(2,'0');$('#chapterName').textContent=['Перевал Серых сосен','Затонувшая часовня','Курган безымянных'][((state.stage-1)%3)];$('#goldCount').textContent=`◈ ${state.gold}`;$('#objective').textContent=`Разбейте дозор · ${aliveEnemies().length} враг${aliveEnemies().length===1?'':'а'}`;$('#turnText').textContent=`Ход ${state.turn}`;$('#phaseText').textContent=state.phase==='hero'?'Ваш ход':'Ход противника';$('#partyStatus').textContent=state.phase==='enemy'?'Враги действуют':selectedUnit()?`${selectedUnit().name} · ${state.used[selected]?'действовал':'готов к бою'}`:'Выберите бойца';
56:  $('#skillLabel').textContent=selectedUnit()?.skill||'особое действие';
57:  document.querySelectorAll('.action').forEach(b=>b.classList.toggle('active',b.dataset.action===action));
58:  board.innerHTML='';let u=selectedUnit();
59:  for(let y=0;y<H;y++)for(let x=0;x<W;x++){let idx=y*W+x,t=state.terrain[idx],tile=document.createElement('div');tile.className=`tile ${t}`;tile.dataset.x=x;tile.dataset.y=y;if(t==='obstacle')tile.dataset.mark='♜';if(t==='water')tile.dataset.mark='≈';
60:  if(u&&state.phase==='hero'&&!state.used[u.id]&&action==='move'&&canMove(x,y,u))tile.classList.add('valid');if(u&&action==='skill'&&aliveEnemies().some(e=>distance(u,e)<=u.range&&e.x===x&&e.y===y))tile.classList.add('target');
61:  let unit=at(x,y);if(unit){let isHero=state.heroes.includes(unit),el=document.createElement('div');el.className=`unit ${isHero?'hero':'enemy'} ${unit.id===selected?'active':''} ${state.used[unit.id]?'acted':''}`;el.dataset.id=unit.id;el.innerHTML=`${isHero&&unit.id==='bryn'?'<span class="rank">I</span>':''}<span class="avatar">${unit.icon}</span><span class="unit-name">${unit.name}</span><span class="hpbar"><i style="width:${Math.max(0,unit.hp/unit.max*100)}%"></i></span>${state.defending[unit.id]?'<span class="shield">◈</span>':''}`;tile.appendChild(el)}
62:  tile.addEventListener('click',()=>onTile(x,y));board.appendChild(tile)}
63:  $('#roster').innerHTML=state.heroes.map(h=>`<article class="hero-card ${h.id===selected?'chosen':''} ${h.hp<=0?'down':''}" data-hero="${h.id}"><div class="hero-head"><span class="face">${h.icon}</span><strong>${h.name}</strong></div><small>${h.role}</small><div class="hero-stats"><span>❤ ${Math.max(0,h.hp)}/${h.max}</span><span>⚔ ${h.atk}</span></div><div class="tinybar"><i style="width:${Math.max(0,h.hp/h.max*100)}%"></i></div></article>`).join('');
64:  document.querySelectorAll('.hero-card').forEach(c=>c.onclick=()=>{if(state.phase!=='hero')return;selected=c.dataset.hero;render()});$('#endTurnBtn').disabled=state.phase!=='hero';$('#endTurnBtn').style.opacity=state.phase==='hero'?'1':'.55';$('#hint').textContent=state.phase==='hero'?(action==='move'?'Подсвеченные клетки — куда можно переместиться.':'Выберите бойца и коснитесь противника в радиусе действия.'):'Противники выбирают цель и атакуют.';
65: }
66: function onTile(x,y){if(state.phase!=='hero'||busy)return;let unit=at(x,y),u=selectedUnit();if(unit&&state.heroes.includes(unit)){selected=unit.id;render();return}if(!u){note('Сначала выберите бойца отряда');return}if(state.used[u.id]){note(`${u.name} уже действовал в этом ходу`);return}if(action==='move'){if(canMove(x,y,u)){u.x=x;u.y=y;state.used[u.id]=true;addLog(`${u.name} перемещается по полю.`);action='attack';save();render();checkWin()}else note('Эта клетка недоступна');return}if(unit&&state.enemies.includes(unit)){if(action==='attack')attack(u,unit,false);else if(action==='skill')skill(u,unit);else note('Выберите действие «Удар» или «Умение»');return}if(action==='wait'){state.defending[u.id]=true;state.used[u.id]=true;addLog(`${u.name} принимает защитную стойку.`);save();render();return}if(action==='attack'||action==='skill')note('Коснитесь противника в пределах досягаемости')}
67: function attack(attacker,target,isEnemy){if(distance(attacker,target)>attacker.range){note('Противник слишком далеко');return}let dmg=attacker.atk+Math.floor(Math.random()*3);if(state.defending[target.id]){dmg=Math.max(1,Math.floor(dmg/2));delete state.defending[target.id]}target.hp=Math.max(0,target.hp-dmg);tone(isEnemy?220:390);addLog(`${attacker.name} наносит ${target.name} ${dmg} урона${target.hp===0?' — противник повержен':''}.`);if(!isEnemy)state.used[attacker.id]=true;save();render();if(!checkWin()&&target.hp===0)toast('Противник повержен')}
68: function skill(u,target){if(distance(u,target)>u.range){note('Цель вне радиуса умения');return}if(u.id==='bryn'){let dmg=u.atk+5;target.hp=Math.max(0,target.hp-dmg);u.hp=Math.min(u.max,u.hp+4);addLog(`Брин проводит щитовой натиск: ${dmg} урона и +4 здоровья.`)}else if(u.id==='lyra'){let dmg=u.atk+6;target.hp=Math.max(0,target.hp-dmg);addLog(`Лира выпускает меткий выстрел: ${dmg} урона.`)}else{let dmg=u.atk+4;target.hp=Math.max(0,target.hp-dmg);let other=aliveEnemies().filter(e=>e!==target&&distance(e,target)<=1)[0];if(other){other.hp=Math.max(0,other.hp-4);addLog(`Орен высвобождает искру руны: ${dmg} урона и цепной разряд!`)}else addLog(`Орен высвобождает искру руны: ${dmg} урона.`)}state.used[u.id]=true;action='attack';save();render();checkWin()}
69: function setAction(a){action=a;render();if(a==='move')note('Выберите подсвеченную клетку для перемещения');else if(a==='skill')note(selectedUnit()?.skill||'Выберите умение')}
70: document.querySelectorAll('.action').forEach(b=>b.onclick=()=>{if(state.phase!=='hero')return;if(!selectedUnit()){note('Выберите бойца');return}if(state.used[selected]){note('Этот боец уже действовал');return}setAction(b.dataset.action)});
71: function neighbors(x,y){return [[x+1,y],[x-1,y],[x,y+1],[x,y-1]].filter(([a,b])=>a>=0&&a<W&&b>=0&&b<H&&state.terrain[b*W+a]!=='obstacle'&&state.terrain[b*W+a]!=='water')}
72: function enemyTurn(){if(state.phase!=='hero'||busy)return;busy=true;state.phase='enemy';render();addLog('Противник идёт в атаку.');let alive=[...aliveEnemies()];let i=0;function step(){if(i>=alive.length){finishEnemyTurn();return}let e=alive[i++];if(e.hp<=0){step();return}let targets=state.heroes.filter(h=>h.hp>0);if(!targets.length){finishEnemyTurn();return}targets.sort((a,b)=>distance(e,a)-distance(e,b));let target=targets[0];if(distance(e,target)>e.range){let opts=neighbors(e.x,e.y).filter(([x,y])=>!at(x,y));opts.sort((a,b)=>(Math.abs(a[0]-target.x)+Math.abs(a[1]-target.y))-(Math.abs(b[0]-target.x)+Math.abs(b[1]-target.y)));if(opts.length){e.x=opts[0][0];e.y=opts[0][1]}}if(distance(e,target)<=e.range){attack(e,target,true)}render();setTimeout(step,470)}setTimeout(step,350)}
73: function finishEnemyTurn(){if(state.heroes.every(h=>h.hp<=0)){busy=false;state.phase='hero';render();showModal(false);return}state.turn++;state.phase='hero';state.used={};state.defending={};busy=false;selected=state.heroes.find(h=>h.hp>0)?.id||null;action='attack';save();render();toast('Ваш ход');}
74: function checkWin(){if(aliveEnemies().length===0){state.gold+=12+state.stage*2;state.heroes.forEach(h=>{if(h.hp>0)h.hp=Math.min(h.max,h.hp+5)});save();showModal(true);return true}if(state.heroes.every(h=>h.hp<=0)){showModal(false);return true}return false}
75: function showModal(win){$('#modalIcon').textContent=win?'🏆':'🕯️';$('#modalTitle').textContent=win?'Перевал очищен':'Отряд пал';$('#modalText').textContent=win?`Дозор разбит. Вы нашли ${12+state.stage*2} серебряных монет. Отряд перевёл дух и восстановил 5 здоровья. Дальше путь ведёт к новым опасностям.`:'Тьма сомкнулась над перевалом. Попробуйте снова — прогресс сохраняется на этом устройстве.';$('#modalBtn').textContent=win?'Продолжить путь':'Начать заново';$('#modal').classList.add('show');busy=false}
76: $('#modalBtn').onclick=()=>{let win=$('#modalTitle').textContent==='Перевал очищен';$('#modal').classList.remove('show');if(win){state=fresh(state.stage+1,state.gold,state.heroes);log=[];selected=state.heroes.find(h=>h.hp>0)?.id||null}else{state=fresh(1,24);log=[];selected='bryn'}save();render()};
77: $('#endTurnBtn').onclick=enemyTurn;$('#restartBtn').onclick=()=>{if(confirm('Начать приключение заново? Текущий бой будет сброшен.')){state=fresh(1,24);selected='bryn';action='attack';log=[];save();render();toast('Приключение началось')}};
78: $('#logBtn').onclick=()=>$('#logPanel').classList.toggle('show');document.addEventListener('click',e=>{if(!e.target.closest('#logPanel')&&!e.target.closest('#logBtn'))$('#logPanel').classList.remove('show')});$('#soundBtn').onclick=()=>{sound=!sound;$('#soundBtn').textContent=sound?'♫':'♪';toast(sound?'Звук включён':'Звук выключен')};
79: render();addLog('Отряд достиг перевала. Впереди замечен вражеский дозор.');
80: if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
81: })();
82: </script>
