(()=>{'use strict';
const W=5,H=6,SAVE='steel-and-runes-save-v2';
const races={human:{name:'Человек',icon:'🧑',passive:'+2 здоровья',hp:2,range:0,armor:0},sylvan:{name:'Сильван',icon:'🧝',passive:'+1 дальность атаки',hp:0,range:1,armor:0},stone:{name:'Камнерождённый',icon:'⛏️',passive:'−1 входящий урон',hp:0,range:0,armor:1},ember:{name:'Пепельнорождённый',icon:'🔥',passive:'усиленное горение',hp:0,range:0,armor:0}};
const classes={sentinel:{name:'Страж',icon:'🛡️',hp:32,atk:7,range:1,skill:'Щитовой натиск',desc:'Удар + укрепление: снижает следующий урон.'},ranger:{name:'Следопыт',icon:'🏹',hp:24,atk:6,range:3,skill:'Связующий выстрел',desc:'Дальний удар обездвиживает цель на ход.'},arcanist:{name:'Рунник',icon:'🔮',hp:22,atk:5,range:3,skill:'Всплеск пламени',desc:'Поражает цель и соседей, оставляет горение.'},duelist:{name:'Дуэлянт',icon:'⚔️',hp:25,atk:8,range:1,skill:'Рваный выпад',desc:'Мощный удар; цель получает уязвимость.'},warden:{name:'Хранитель',icon:'🌿',hp:28,atk:6,range:2,skill:'Живая кора',desc:'Лечит союзника или наносит урон и укрепляет себя.'},medic:{name:'Лекарь',icon:'✨',hp:23,atk:5,range:3,skill:'Целительный свет',desc:'Исцеляет союзника в пределах 3 клеток.'}};
const names=['Брин','Лира','Орен'],defaults=[['stone','sentinel'],['sylvan','ranger'],['ember','arcanist']];let state,action='attack',selected=null,log=[],sound=true,busy=false;
const $=s=>document.querySelector(s),board=$('#board');
function makeHero(i,race=defaults[i][0],klass=defaults[i][1],old={}){const c=classes[klass],r=races[race];return{id:['bryn','lyra','oren'][i],name:names[i],race,klass,role:c.name,icon:r.icon,hp:old.hp??c.hp+r.hp,max:c.hp+r.hp,atk:c.atk,range:c.range+r.range,x:[1,2,3][i],y:5,skill:c.skill,armor:r.armor,status:old.status||{},cd:old.cd||0}}
function terrainFor(stage){let a=Array(W*H).fill('floor'),seed=stage*997+19,rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};for(let i=0;i<a.length;i++){let y=Math.floor(i/W);if(y===5||y===0)continue;let n=rand();a[i]=n<.13?'moss':n<.25?'rough':n<.32?'water':'floor'}for(let i=0;i<3;i++){let x=1+Math.floor(rand()*3),y=1+Math.floor(rand()*4),idx=y*W+x;if(a[idx]!=='water')a[idx]='obstacle'}return a}
const mapNames=['Перевал Серых сосен','Затонувшая часовня','Курган безымянных','Пепельная чаща','Зеркальные топи','Крепость расколотой луны'];
const enemyTypes=[{kind:'raider',name:'Налётчик',icon:'👺',hp:17,atk:5,range:1},{kind:'wolf',name:'Сумрачный волк',icon:'🐺',hp:14,atk:5,range:1},{kind:'archer',name:'Лесной стрелок',icon:'🏹',hp:13,atk:4,range:3},{kind:'shaman',name:'Топляк-шаман',icon:'👻',hp:16,atk:4,range:2},{kind:'brute',name:'Болотный громила',icon:'👹',hp:25,atk:7,range:1}];
function enemiesFor(stage){let count=stage%3===0?5:4,scale=Math.floor((stage-1)/2),types=stage%3===0?[4,2,0,3,1]:stage%2?[0,1,2,0,3]:[3,2,1,4,0],pos=[[1,0],[3,0],[4,1],[0,2],[2,1]];return types.slice(0,count).map((ti,i)=>{let t=enemyTypes[ti];return{...t,id:`${t.kind}${i}`,hp:t.hp+scale*2,max:t.hp+scale*2,atk:t.atk+Math.floor((stage-1)/4),x:pos[i][0],y:pos[i][1],status:{}}})}
function fresh(stage=1,gold=24,heroes){return{stage,gold,turn:1,phase:'hero',heroes:heroes||defaults.map((d,i)=>makeHero(i)),enemies:enemiesFor(stage),used:{},defending:{},terrain:terrainFor(stage)}}
function load(){try{let x=JSON.parse(localStorage.getItem(SAVE)||localStorage.getItem('steel-and-runes-save-v1'));if(x?.heroes&&x?.enemies){x.heroes=x.heroes.map((h,i)=>{if(!h.klass)return makeHero(i,defaults[i][0],['sentinel','ranger','arcanist'][i],h);let d=makeHero(i,h.race||defaults[i][0],h.klass,h);return{...d,...h,role:classes[h.klass].name,skill:classes[h.klass].skill,armor:races[h.race||defaults[i][0]].armor}});x.heroes.forEach(h=>{h.status||={};h.cd||=0});return x}}catch(e){}return fresh()}
state=load();selected=state.heroes.find(h=>h.hp>0)?.id||null;
function save(){try{localStorage.setItem(SAVE,JSON.stringify(state))}catch(e){}}
function note(msg){let n=$('#boardNote');n.textContent=msg;n.classList.add('show');clearTimeout(note.t);note.t=setTimeout(()=>n.classList.remove('show'),2100)}function toast(msg){let t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),1700)}
function tone(freq=360){if(!sound)return;try{let C=window.AudioContext||window.webkitAudioContext;if(!C)return;let ctx=tone.ctx||(tone.ctx=new C()),osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=freq;gain.gain.setValueAtTime(.035,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.12);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.13)}catch(e){}}
function addLog(text){log.unshift(text);log=log.slice(0,24);$('#logList').innerHTML=log.map(x=>`<li>${x}</li>`).join('')}
function units(){return[...state.heroes,...state.enemies].filter(u=>u.hp>0)}function at(x,y){return units().find(u=>u.x===x&&u.y===y)}function selectedUnit(){return state.heroes.find(h=>h.id===selected&&h.hp>0)}function aliveEnemies(){return state.enemies.filter(e=>e.hp>0)}function distance(a,b){return Math.abs(a.x-b.x)+Math.abs(a.y-b.y)}function canMove(x,y,u){return x>=0&&x<W&&y>=0&&y<H&&!at(x,y)&&!['obstacle','water'].includes(state.terrain[y*W+x])&&distance(u,{x,y})<=2}
function skillTarget(u,t){if(u.klass==='medic')return state.heroes.includes(t);if(u.klass==='warden')return state.heroes.includes(t)||state.enemies.includes(t);return state.enemies.includes(t)}
function render(){const stage=state.stage;$('#battleNum').textContent=String(stage).padStart(2,'0');$('#chapterName').textContent=mapNames[(stage-1)%mapNames.length];$('#goldCount').textContent=`◈ ${state.gold}`;$('#objective').textContent=`Зачистить поле · ${aliveEnemies().length} врагов`;$('#turnText').textContent=`Ход ${state.turn}`;$('#phaseText').textContent=state.phase==='hero'?'Ваш ход':'Ход противника';let su=selectedUnit();$('#partyStatus').textContent=state.phase==='enemy'?'Враги действуют':su?`${su.name} · ${state.used[selected]?'действовал':'готов к бою'}`:'Выберите бойца';$('#skillLabel').textContent=su?(su.cd?`перезарядка ${su.cd}`:su.skill):'особое действие';
 document.querySelectorAll('.action').forEach(b=>{b.classList.toggle('active',b.dataset.action===action);b.disabled=state.phase!=='hero'||!su||!!state.used[selected]||(b.dataset.action==='skill'&&su.cd>0)});board.innerHTML='';let u=su;
 for(let y=0;y<H;y++)for(let x=0;x<W;x++){let idx=y*W+x,t=state.terrain[idx],tile=document.createElement('div');tile.className=`tile ${t}`;tile.dataset.x=x;tile.dataset.y=y;if(t==='obstacle')tile.dataset.mark='♜';if(t==='water')tile.dataset.mark='≈';if(t==='moss')tile.dataset.mark='✿';if(u&&state.phase==='hero'&&!state.used[u.id]&&action==='move'&&canMove(x,y,u))tile.classList.add('valid');let occupant=at(x,y);if(u&&action==='skill'&&occupant&&skillTarget(u,occupant))tile.classList.add('target');if(occupant){let hero=state.heroes.includes(occupant),el=document.createElement('div');el.className=`unit ${hero?'hero':'enemy'} ${occupant.id===selected?'active':''} ${state.used[occupant.id]?'acted':''}`;let badge=occupant.status?.burn?'🔥':occupant.status?.root?'❄':occupant.status?.vulnerable?'☠':state.defending[occupant.id]?'◈':'';el.innerHTML=`<span class="avatar">${occupant.icon}</span><span class="unit-name">${occupant.name}</span><span class="hpbar"><i style="width:${Math.max(0,occupant.hp/occupant.max*100)}%"></i></span>${badge?`<span class="status">${badge}</span>`:''}`;tile.appendChild(el)}tile.addEventListener('click',()=>onTile(x,y));board.appendChild(tile)}
 $('#roster').innerHTML=state.heroes.map(h=>`<article class="hero-card ${h.id===selected?'chosen':''} ${h.hp<=0?'down':''}" data-hero="${h.id}"><div class="hero-head"><span class="face">${races[h.race]?.icon||h.icon}</span><strong>${h.name}</strong></div><small>${races[h.race]?.name||''} · ${h.role}</small><div class="hero-stats"><span>❤ ${Math.max(0,h.hp)}/${h.max}</span><span>⚔ ${h.atk} · ${h.range}◉</span></div><div class="tinybar"><i style="width:${Math.max(0,h.hp/h.max*100)}%"></i></div></article>`).join('');document.querySelectorAll('.hero-card').forEach(c=>c.onclick=()=>{if(state.phase==='hero'){selected=c.dataset.hero;render()}});
 $('#endTurnBtn').disabled=state.phase!=='hero';$('#endTurnBtn').style.opacity=state.phase==='hero'?'1':'.55';$('#hint').textContent=state.phase!=='hero'?'Враги выбирают цель и атакуют.':action==='move'?'Подсвеченные клетки — куда можно переместиться.':action==='skill'?(su?.klass==='medic'||su?.klass==='warden'?'Выберите раненого союзника для помощи или врага для удара.':'Выберите отмеченную цель для умения.'):'Выберите бойца, действие и цель. Укрытие снижает урон.';$('#manageParty').disabled=state.phase!=='hero'||state.turn!==1||Object.keys(state.used).length>0;$('#manageParty').style.opacity=$('#manageParty').disabled?'.45':'1'}

