function onTile(x,y){if(state.phase!=='hero'||busy)return;let target=at(x,y),u=selectedUnit();if(target&&state.heroes.includes(target)&&!(action==='skill'&&u&&skillTarget(u,target))){selected=target.id;render();return}if(!u){note('Сначала выберите бойца отряда');return}if(state.used[u.id]){note(`${u.name} уже действовал в этом ходу`);return}if(action==='move'){if(canMove(x,y,u)){u.x=x;u.y=y;state.used[u.id]=true;addLog(`${u.name} занимает новую позицию.`);action='attack';save();render()}else note('Эта клетка недоступна');return}if(target){if(action==='attack'){if(!state.enemies.includes(target)){note('Обычный удар нельзя направить на союзника');return}attack(u,target,false)}else if(action==='skill'){if(!skillTarget(u,target)){note('Эта цель недоступна для умения');return}skill(u,target)}else note('Выберите действие «Удар» или «Умение»');return}if(action==='wait'){state.defending[u.id]=true;state.used[u.id]=true;addLog(`${u.name} принимает защитную стойку.`);save();render();return}if(action==='attack'||action==='skill')note('Коснитесь подходящей цели')}
function damage(attacker,target,base,opts={}){let n=base+(opts.fixed?0:Math.floor(Math.random()*3));if(target.status?.vulnerable){n+=2;delete target.status.vulnerable}if(target.status?.guard){n=Math.max(1,n-2);delete target.status.guard}if(state.defending[target.id]){n=Math.max(1,Math.floor(n/2));delete state.defending[target.id]}if(state.terrain[target.y*W+target.x]==='rough')n=Math.max(1,n-1);if(state.heroes.includes(target))n=Math.max(1,n-(target.armor||0));target.hp=Math.max(0,target.hp-n);return n}
function attack(attacker,target,isEnemy){if(distance(attacker,target)>attacker.range){note('Противник слишком далеко');return}let d=damage(attacker,target,attacker.atk);tone(isEnemy?220:390);addLog(`${attacker.name} наносит ${target.name} ${d} урона${target.hp===0?' — цель повержена':''}.`);if(!isEnemy)state.used[attacker.id]=true;save();render();if(!checkWin()&&target.hp===0)toast('Противник повержен')}
function skill(u,target){if(u.cd>0){note(`Умение будет готово через ${u.cd} хода`);return}let k=u.klass;if(k==='medic'){if(target.hp>=target.max){note('У союзника и так полные силы');return}let heal=Math.min(9,target.max-target.hp);target.hp+=heal;addLog(`${u.name} исцеляет ${target.name}: +${heal} здоровья.`)}else if(k==='warden'&&state.heroes.includes(target)){let heal=Math.min(6,target.max-target.hp);target.hp+=heal;target.status.guard=true;addLog(`${u.name} укрывает ${target.name} живой корой: +${heal} здоровья и защита.`)}else if(k==='warden'){let d=damage(u,target,u.atk+3,{fixed:true});u.status.guard=true;addLog(`${u.name} оплетает ${target.name}: ${d} урона; сам получает защиту.`)}else if(k==='sentinel'){let d=damage(u,target,u.atk+5,{fixed:true});u.status.guard=true;addLog(`${u.name} проводит щитовой натиск: ${d} урона и укрепляется.`)}else if(k==='ranger'){let d=damage(u,target,u.atk+4,{fixed:true});target.status.root=1;addLog(`${u.name} выпускает связующий выстрел: ${d} урона, цель обездвижена.`)}else if(k==='arcanist'){let d=damage(u,target,u.atk+3,{fixed:true});target.status.burn=2;let others=aliveEnemies().filter(e=>e!==target&&distance(e,target)<=1);others.forEach(e=>{e.hp=Math.max(0,e.hp-3);e.status.burn=1});addLog(`${u.name} вызывает всплеск пламени: ${d} урона${others.length?' и задевает соседей':''}.`)}else if(k==='duelist'){let d=damage(u,target,u.atk+5,{fixed:true});target.status.vulnerable=true;u.status.guard=true;addLog(`${u.name} проводит рваный выпад: ${d} урона; цель уязвима.`)}u.cd=3;state.used[u.id]=true;action='attack';tone(500);save();render();checkWin()}

