function checkWin(){if(aliveEnemies().length===0){let reward=12+state.stage*2;state.gold+=reward;state.heroes.forEach(h=>{if(h.hp>0)h.hp=Math.min(h.max,h.hp+5);else h.hp=Math.max(8,Math.ceil(h.max*.35));h.status={};h.cd=0});save();showModal(true);return true}if(state.heroes.every(h=>h.hp<=0)){showModal(false);return true}return false}
function neighbors(x,y){return[[x+1,y],[x-1,y],[x,y+1],[x,y-1]].filter(([a,b])=>a>=0&&a<W&&b>=0&&b<H&&!['obstacle','water'].includes(state.terrain[b*W+a]))}
function enemyTurn(){if(state.phase!=='hero'||busy)return;busy=true;state.phase='enemy';render();addLog('Противник идёт в атаку.');let alive=[...aliveEnemies()],i=0;function step(){if(i>=alive.length){finishEnemyTurn();return}let e=alive[i++];if(e.hp<=0){step();return}if(e.status?.burn){let burn=3;e.hp=Math.max(0,e.hp-burn);e.status.burn--;addLog(`${e.name} получает ${burn} урона от огня.`);if(!e.status.burn)delete e.status.burn;if(e.hp<=0){render();if(checkWin())return;setTimeout(step,250);return}}let targets=state.heroes.filter(h=>h.hp>0);if(!targets.length){finishEnemyTurn();return}targets.sort((a,b)=>distance(e,a)-distance(e,b));let target=targets[0],rooted=!!e.status.root;if(rooted){delete e.status.root;addLog(`${e.name} не может сдвинуться с места.`)}else if(distance(e,target)>e.range){let opts=neighbors(e.x,e.y).filter(([x,y])=>!at(x,y));opts.sort((a,b)=>(Math.abs(a[0]-target.x)+Math.abs(a[1]-target.y))-(Math.abs(b[0]-target.x)+Math.abs(b[1]-target.y)));if(opts.length){e.x=opts[0][0];e.y=opts[0][1]}}if(distance(e,target)<=e.range){let d=damage(e,target,e.atk);addLog(`${e.name} атакует ${target.name}: ${d} урона.`);if(target.hp<=0)addLog(`${target.name} падает без сил.`)}render();if(state.heroes.every(h=>h.hp<=0)){finishEnemyTurn();return}setTimeout(step,360)}setTimeout(step,320)}
