$('#modalBtn').onclick=()=>{let win=$('#modalTitle').textContent==='Победа!';$('#modal').classList.remove('show');if(win){state=fresh(state.stage+1,state.gold,state.heroes);log=[];selected=state.heroes.find(h=>h.hp>0)?.id||null;addLog('Отряд вступил на новый участок Серого предела.')}else{state=fresh(1,24);log=[];selected=state.heroes[0].id;addLog('Отряд собрался у начала пути.')}action='attack';save();render()};

